DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.enforce_two_person_approval()'::regprocedure) INTO d; d:=replace(d,'IF amt<=2000 THEN RETURN NEW; END IF;','IF amt<=2000 THEN RETURN NEW; END IF; IF TG_OP=''INSERT'' AND NEW.status NOT IN (''approved'',''completed'') THEN RETURN NEW; END IF;'); EXECUTE d; END $$;
CREATE OR REPLACE FUNCTION public.staff_service_case_source() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status NOT IN ('completed','cancelled','rejected') THEN INSERT INTO staff_cases(source_kind,source_id,city_id,department,title,next_action,due_at,created_at) VALUES('service_bookings',NEW.id::text,NEW.city_id,'support','خدمت بکنگ کی نگرانی','مجاز خدمت اور بکنگ کا جائزہ',staff_case_deadline('support',NEW.created_at),NEW.created_at) ON CONFLICT(source_kind,source_id) DO NOTHING; ELSE UPDATE staff_cases SET status='review',next_action='خدمت کے نتیجے اور ثبوت کی تصدیق',updated_at=now() WHERE source_kind='service_bookings' AND source_id=NEW.id::text AND status NOT IN ('resolved','review'); END IF; RETURN NEW; END $$;
CREATE TRIGGER staff_case_service AFTER INSERT OR UPDATE OF status ON public.service_bookings FOR EACH ROW EXECUTE FUNCTION public.staff_service_case_source(); REVOKE ALL ON FUNCTION public.staff_service_case_source() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.staff_request_exact_refund(_kind text,_order uuid,_amount numeric,_type text,_note text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE customer uuid; BEGIN IF NOT staff_order_allowed('support',_kind,_order) OR _type NOT IN ('wallet','original') THEN RAISE EXCEPTION 'Refund scope or type denied'; END IF; IF _kind='food' THEN SELECT customer_id INTO customer FROM orders WHERE id=_order; ELSIF _kind='grocery_cart' THEN SELECT customer_id INTO customer FROM grocery_cart_orders WHERE id=_order; ELSIF _kind='grocery_list' THEN SELECT customer_id INTO customer FROM grocery_list_orders WHERE id=_order; ELSIF _kind='service' THEN SELECT customer_id INTO customer FROM service_bookings WHERE id=_order; END IF; IF customer IS NULL THEN RAISE EXCEPTION 'Order customer required'; END IF; RETURN request_secure_approval('refund',_order,_amount,jsonb_build_object('order_id',_order,'order_kind',_kind,'customer_id',customer,'amount',_amount,'refund_type',_type),_note); END $$;
REVOKE ALL ON FUNCTION public.staff_request_exact_refund(text,uuid,numeric,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.staff_request_exact_refund(text,uuid,numeric,text,text) TO authenticated,service_role;